#include<iostream>
using namespace std;
int k, m, n;
int lan[30010];
int hp[30010];
int x;
int boss_hp;
int con;
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	cin >> k >> m >> n;
	for (int i = 0; i < m; i++) {
		boss_hp = n;
		cin >> lan[i] >> hp[i];
		if (lan[i] != 0) {
			if (lan[i] <= k) {
				for (int ki = 0; ki < k / lan[i]; ki++) {
					if (boss_hp > 0) {
						boss_hp -= hp[i];
						if (boss_hp <= 0) {
							cout << i + 1 << " ";
							break;
						}
					} else {
						cout << i + 1 << " ";
						break;
					}
				}
				if (boss_hp > 0) {
					con++;
				}
			} else {
				con++;
			}
		} else {
			cout << i + 1 << " ";
		}
	}
	if (con == m)cout << "-1";
	return 0;
}

